import{_ as r,o as a,c as s,a2 as p}from"./chunks/framework.BXzK3EA4.js";const n="/assets/%E6%8E%A7%E5%88%B6%E5%8F%B0%E4%BA%A7%E5%93%81.CNePglaf.png",e="/assets/%E9%80%89%E6%8B%A9%E4%B8%80%E4%B8%AA%E7%8B%AC%E6%9C%8D%E4%BA%A7%E5%93%81.D_Z06IlV.png",o="/assets/%E7%AB%8B%E5%8D%B3%E8%AE%A2%E8%B4%AD%E7%8B%AC%E6%9C%8D.w_Rs7k-f.png",i="/assets/%E7%AB%8B%E5%8D%B3%E8%AE%A2%E8%B4%AD%E7%8B%AC%E6%9C%8D11.Bs27obzH.png",l="/assets/%E7%89%A9%E7%90%86%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%B4%AD%E7%89%A9%E8%BD%A6%E9%85%8D%E7%BD%AE.CM1Jjv8j.png",d="/assets/%E7%99%BB%E5%BD%95rak%E5%AE%98%E7%BD%91.Dg4J8-fU.png",g="/assets/%E7%99%BB%E5%BD%95raksmart%E6%8E%A7%E5%88%B6%E5%8F%B0.DGZE5lRz.png",E="/assets/%E7%8B%AC%E6%9C%8D%E8%B4%AD%E7%89%A9%E8%BD%A611.C9-Ces71.png",c="/assets/%E9%80%89%E6%8B%A9%E5%9C%B0%E5%8C%BA%E5%92%8C%E5%88%86%E7%B1%BB.BOMD2caI.png",m="/assets/%E7%AB%8B%E5%8D%B3%E8%B4%AD%E4%B9%B0%E7%8B%AC%E6%9C%8D11.DeOQLuQB.png",h="/assets/%E7%8B%AC%E6%9C%8D%E7%BB%93%E7%AE%9711.CpFG1WOR.png",B="/assets/%E7%8B%AC%E6%9C%8D%E7%BB%93%E7%AE%971.C8ae1xm3.png",A="/assets/%E7%8B%AC%E6%9C%8D%E5%B7%B2%E7%BB%93%E7%AE%97.DTmwx3KH.png",_="/assets/%E6%9F%A5%E7%9C%8B%E6%9C%8D%E5%8A%A1%E5%99%A8%E7%8A%B6%E6%80%811.CioWUYck.png",q=JSON.parse('{"title":"购买物理服务器","description":"","frontmatter":{"title":"购买物理服务器"},"headers":[],"relativePath":"dedicatedserver/quickstart/purchase.md","filePath":"dedicatedserver/quickstart/purchase.md","lastUpdated":1793696072000}'),b={name:"dedicatedserver/quickstart/purchase.md"};function D(k,t,u,C,P,f){return a(),s("div",null,[...t[0]||(t[0]=[p('<p>本文主要介绍如何通过 RakSmart 官网产品入口和控制台入口购买物理服务器。</p><hr><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ol><li><p>注册 RakSmart 账号，详细步骤可参考<a href="https://cn.raksmart.com/login/index.html" target="_blank" rel="noreferrer">注册 RakSmart 账号</a>。</p></li><li><p>了解 RakSmart 产品和配置项、计费周期、付款方式等信息，参考<a href="/beginners-guide/buy-products/purchase.html">购买 RakSmart 产品</a>。</p></li></ol><hr><h3 id="通过官网产品入口购买" tabindex="-1">通过官网产品入口购买 <a class="header-anchor" href="#通过官网产品入口购买" aria-label="Permalink to &quot;通过官网产品入口购买&quot;">​</a></h3><p>您可以直接通过 RakSmart 官网顶部导航入口购买物理服务器。</p><ol><li><p>使用注册的 RakSmart 账号登录 <a href="https://cn.raksmart.com/" target="_blank" rel="noreferrer">RakSmart 官网</a>。</p></li><li><p>将鼠标悬停在顶部导航<strong>物理服务器</strong>，打开下拉列表。</p><p><img src="'+n+'" alt="控制台产品.png"></p></li><li><p>选择一个物理服务器产品类型，进入产品页面。</p><p><img src="'+e+'" alt="选择一个独服产品.png"></p></li><li><p>单击<strong>立即订购</strong>。</p><p><img src="'+o+'" alt="立即订购独服.png"></p></li><li><p>在产品清单页面，选择购买物理服务器的地区、配置，单击<strong>现在订购</strong>。</p><p><img src="'+i+'" alt="立即订购独服11.png"></p></li><li><p>在<strong>配置</strong> - <strong>购物</strong>车页面，参考如下信息完成自定义产品配置。各配置项详细说明，请参考<a href="#配置项及付款流程说明">配置项及付款流程说明</a>。</p><p><img src="'+l+'" alt="物理服务器购物车配置.png"></p></li></ol><hr><h3 id="通过控制台入口购买" tabindex="-1">通过控制台入口购买 <a class="header-anchor" href="#通过控制台入口购买" aria-label="Permalink to &quot;通过控制台入口购买&quot;">​</a></h3><p>本文主要介绍通过 RakSmart 控制台购买中心入口购买物理服务器。</p><ol><li><p>使用注册的 RakSmart 账号登录 <a href="https://cn.raksmart.com/login/index.html" target="_blank" rel="noreferrer">RakSmart 官网</a>。</p><p><img src="'+d+'" alt="登录rak官网.png"></p></li><li><p>在官网顶部导航右侧，单击<strong>控制台</strong>，进入控制台<strong>客户中心</strong>页面。</p><p><img src="'+g+'" alt="登录raksmart控制台.png"></p></li><li><p>单击<strong>购买中心</strong>，进入<strong>购物车</strong> - <strong>物理服务器</strong>面板。</p><p><img src="'+E+'" alt="独服购物车11.png"></p></li><li><p>选择地区、分类、核心数等产品信息，单击<strong>立即订购</strong>。进入<strong>配置</strong> - <strong>购物车</strong>页面。各配置项详细说明，请参考<a href="#配置项及付款流程说明">配置项及付款流程说明</a>。</p><p><img src="'+c+'" alt="选择地区和分类.png"></p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>地区</td><td>物理服务器部署的可用区。目前支持的区域和可用区有美洲的硅谷、洛杉矶、西雅图，亚洲的香港、台湾、东京等区和欧洲的法兰克福。关于区域和可用区的详细介绍可参考 区域和可用区。</td></tr><tr><td>分类</td><td>物理服务器的功能和配置类型，主要包括按如下分类：<br>-标配机型：基础标准配置，满足常规业务，如网站部署、轻量应用运行的基础算力与资源需求；<br>-站群多 IP：配备更多独立 IP，适配多网站、多域名并行部署的业务场景；<br>-大带宽：提供高带宽资源，适配视频流媒体、数据传输等高网络吞吐需求的业务；<br>-高防：集成抗攻击防护能力，适配易受网络攻击的业务（如电商平台、游戏服务器）。</td></tr><tr><td>核心数</td><td>物理服务器的核心配置选项， 支持通过核心数选择单 CPU / 双 CPU；也支持通过 Gold、Platinum 和 AMD 等 CPU 型号选择。</td></tr></tbody></table></li></ol><hr><h3 id="配置项及付款流程说明" tabindex="-1">配置项及付款流程说明 <a class="header-anchor" href="#配置项及付款流程说明" aria-label="Permalink to &quot;配置项及付款流程说明&quot;">​</a></h3><ol><li><p>服务器设置 主机名称与控制台密码默认由系统生成，支持自定义修改。</p></li><li><p>配置选项<br> 请参考如下信息完成<strong>配置选项</strong>配置。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>带宽类型</td><td>选择带宽线路，如大陆优化 VIP、精品 CN2、国际 BGP；</td></tr><tr><td>操作系统</td><td>服务器运行的系统环境，可选类型包括：<br>- Linux 系统：CentOS、 Ubuntu、Debian、Rocky、Almalinux；<br>- Windows 系统：Windows Server Datacenter 版本。</td></tr><tr><td>自定义装机</td><td>是否开启自定义装机的开关；<br>- 自定义装机是系统安装后对系统或软件的深度预装与部署（含镜像、脚本、应用栈）。</td></tr><tr><td>带宽选择</td><td>选择具体的带宽套餐，如大陆优化 VIP 100M 不限</td></tr><tr><td>IP地址1-5 / 更多IPv4 / 更多IPv6</td><td>系统默认分配 1 个公网 IP，若需要额外购买 IP，可在 IP 地址 2-5 及更多 IPv4 等选项中自行选择。也可以选择不同规格的高防 IP 服务。</td></tr><tr><td>硬盘</td><td>硬盘 1（系统盘）默认包含“1T 机械硬盘”，即系统自带 1TB 容量的机械硬盘，该费用已包含在基础套餐内，无需额外付费；<br>可选升级：可付费升级为“1T 固态硬盘”，即用 1TB 容量的固态硬盘替代默认机械硬盘，需要额外支付费用。</td></tr><tr><td>专用VLAN</td><td>用于构建内网的选项。默认配置&quot;无&quot;，即不启用专用 VLAN，服务器仅通过公网连接。</td></tr></tbody></table></li><li><p>可用增值服务</p><p>可选购的服务器管理面板服务，如 DirectAdmin、cPanel、Plesk 等，不同版本对应不同价格和功能。</p></li><li><p>附加信息</p><p>根据您的业务需求，选择是否开启自动续费的开关。若开启系统将自动从您的账户余额扣款续费；否则到期后服务将暂停。</p></li><li><p>付款周期</p><p>选择服务的购买时长，支持月付、季度付、半年付和年付。</p></li><li><p>数量</p><p>调整购买服务器的台数。</p></li><li><p>完成选择配置后，单击<strong>立即购买</strong>。</p><p><img src="'+m+'" alt="立即购买独服11.png"></p></li><li><p>在确认产品页面支持选择优惠券（若有）和输入备注信息；确认没有问题后，勾选<strong>我已阅读并同意</strong>服务条款，单击<strong>结算</strong>。</p><p><img src="'+h+'" alt="独服结算11.png"></p></li><li><p>在<strong>支付</strong>页面，选择某一种付款方式支付或者使用余额支付。</p><p><img src="'+B+'" alt="独服结算1.png"></p></li><li><p>支付完成后如下图所示。</p><p><img src="'+A+'" alt="独服已结算.png"></p></li></ol><hr><h3 id="操作结果" tabindex="-1">操作结果 <a class="header-anchor" href="#操作结果" aria-label="Permalink to &quot;操作结果&quot;">​</a></h3><p>返回<strong>产品管理</strong>的<strong>物理服务器</strong>列表，您能看到已购的物理服务器。当物理服务器的状态由<strong>审核中</strong>变为<strong>有效的</strong>时，即可以正常使用此物理服务器。</p><p><img src="'+_+'" alt="查看服务器状态1.png"></p><hr><h3 id="后续操作" tabindex="-1">后续操作 <a class="header-anchor" href="#后续操作" aria-label="Permalink to &quot;后续操作&quot;">​</a></h3><p>购买并开通物理服务器后，您可以开始登录并使用物理服务器。参考<a href="./login.html">登录物理服务器</a>。</p>',22)])])}const x=r(b,[["render",D]]);export{q as __pageData,x as default};
